-- Creates the new SAPA workspace without deleting the legacy application.
begin;
create table public.sapa_pic_profiles (
  name text primary key check (length(name) between 1 and 80 and name = upper(btrim(name))),
  created_at timestamptz not null default now()
);
create table public.sapa_pic_settings (
  pic_name text not null references public.sapa_pic_profiles(name) on delete cascade,
  setting_key text not null check (setting_key in ('templates','activeTemplateKey','tableSettings','statuses','darkMode','podTemplate','podDelay','podUseSameTab','podSoundEnabled')),
  value jsonb not null check (octet_length(value::text) <= 200000),
  revision integer not null default 1 check (revision > 0),
  updated_at timestamptz not null default now(),
  primary key (pic_name, setting_key)
);
alter table public.sapa_pic_profiles enable row level security;
alter table public.sapa_pic_settings enable row level security;
revoke all on public.sapa_pic_profiles, public.sapa_pic_settings from public, anon, authenticated;
grant select, insert on public.sapa_pic_profiles to service_role;
grant select, insert, update on public.sapa_pic_settings to service_role;
comment on table public.sapa_pic_profiles is 'Shared PIC workspaces selected without passwords. Not a user authentication system.';
comment on table public.sapa_pic_settings is 'Shared PIC preferences; accessed only via the bounded pic-profiles Edge Function. Generated table images remain client-side.';
insert into public.sapa_pic_profiles(name) values ('ABRAR'),('ANA'),('ATHIRA'),('AYU'),('JENIFER'),('SYAIFUL');
insert into public.sapa_pic_settings(pic_name,setting_key,value)
select p.name, d.key,d.value from public.sapa_pic_profiles p cross join jsonb_each($defaults${"templates":{"template_1":{"id":"template_1","name":"Template 1: Keterlambatan Pengiriman (SLA > 1 Jam / > 2 Jam)","description":"Untuk pesanan dengan keterlambatan SLA pengiriman","content":"Halo Selamat Siang Pak/Bu {nama_ac},\n\nIzin menginformasikan terkait monitoring operasional SAPA Alfagift di wilayah binaan Bapak/Ibu.\nTerdapat kendala keterlambatan pesanan (SLA) pada toko berikut:\n\n{daftar_toko_dan_shipment}\n\nTotal Kendala: {total_shipment} Pesanan ({total_toko} Toko)\nJam Monitoring: {jam} | PIC: {pic}\n\nMohon bantuannya untuk dikoordinasikan ke personil toko terkait agar pengiriman dapat segera diselesaikan/diproses. Detail rincian pesanan terlampir pada gambar tabel di bawah. Terima kasih atas kerjasamanya 🙏"},"template_2":{"id":"template_2","name":"Template 2: Pesanan Belum Dikirim","description":"Untuk pesanan yang belum diserahkan ke kurir / konsumen","content":"Yth. Pak/Bu {nama_ac},\n\nMohon atensinya untuk pesanan Alfagift yang berstatus *Belum Dikirim* di toko binaan Bapak/Ibu:\n\n{daftar_toko_dan_shipment}\n\nTotal: {total_shipment} Pesanan ({total_toko} Toko)\nJam Monitoring: {jam} | PIC: {pic}\n\nMohon bantuannya untuk follow-up ke toko agar segera dilakukan serah terima ke kurir/konsumen dan update status di sistem SAPA.\nTabel detail terlampir. Terima kasih! 🙏"},"template_3":{"id":"template_3","name":"Template 3: Pembatalan Belum Disetujui","description":"Untuk pengajuan cancel order yang menunggu persetujuan","content":"Halo Pak/Bu {nama_ac},\n\nMohon bantuan approval/konfirmasi terkait pengajuan *Pembatalan Pesanan Alfagift* pada toko binaan Bapak/Ibu:\n\n{daftar_toko_dan_shipment}\n\nTotal: {total_shipment} Pengajuan Pembatalan\nJam Monitoring: {jam} | PIC: {pic}\n\nMohon konfirmasi agar status pesanan konsumen tidak menggantung. Rincian pesanan tertera pada gambar tabel terlampir. Terima kasih banyak atas dukungannya! 🙏"},"template_4":{"id":"template_4","name":"Template 4: Custom Template","description":"Template bebas yang disesuaikan kebutuhan operasional","content":"Selamat bertugas Pak/Bu {nama_ac},\n\nBerikut kami kirimkan rekap kendala pesanan Alfagift wilayah {cabang}:\n{daftar_toko_dan_shipment}\n\nTotal: {total_shipment} kendala ({total_toko} toko).\nJam: {jam} | PIC: {pic}\n\nMohon bantuan percepatan penyelesaian. Rincian tabel terlampir di bawah. Terima kasih! 🙏"}},"activeTemplateKey":"template_1","tableSettings":{"showTitleBar":true,"titleBadgeText":"MONITORING SAPA 3","showTitleBadge":true,"showAcName":true,"acNamePrefix":"AC: ","showCabangRegion":true,"showMetaJam":true,"showMetaTotal":true,"showMetaPic":true,"showTopBanner":false,"topBannerText":"⚠️ MOHON DITINDAKLANJUTI SEGERA KE PERSONIL TOKO","topBannerBg":"#FEF08A","topBannerColor":"#854D0E","showFooterNote":false,"footerNoteText":"Catatan: Mohon prioritaskan pesanan dengan SLA > 2 Jam & konfirmasi segera setelah pesanan dikirim.","footerAlign":"left","showWatermark":false,"watermarkText":"ALFAGIFT OPERATIONAL • SAPA 3","columns":{"kodeToko":{"visible":true,"label":"Kode Toko"},"namaToko":{"visible":true,"label":"Nama Toko"},"cabang":{"visible":true,"label":"Cabang"},"region":{"visible":true,"label":"Region"},"shipment":{"visible":true,"label":"Shipment"},"namaKonsumen":{"visible":true,"label":"Nama Konsumen"},"sla":{"visible":true,"label":"SLA"},"jam":{"visible":false,"label":"Jam"},"pic":{"visible":false,"label":"PIC"}},"preset":"excel_classic","colors":{"tableBg":"#ffffff","headerBg":"#f3f4f6","headerText":"#111827","titleBadgeBg":"#dc2626","titleBadgeText":"#ffffff","borderColor":"#d1d5db","innerBorderColor":"#e5e7eb","rowEvenBg":"#ffffff","rowOddBg":"#fafafa","rowTextColor":"#111827","shipmentColor":"#1e40af"},"sla":{"mode":"full_cell","highlightEnabled":true,"color12h":"#cc0000","color6h":"#ef4444","color2h":"#ea580c","color1h":"#f59e0b","color45m":"#facc15","color30m":"#fef08a"},"typography":{"fontFamily":"system","fontSize":"normal","paddingDensity":"normal","borderStyle":"excel","borderRadius":0,"shadow":false},"exportScale":2.5},"statuses":[{"id":"belum_dikerjakan","label":"Belum Dikerjakan / Belum Dihubungi","shortLabel":"Belum Dikerjakan","color":"amber","countsAsCompleted":false,"isDefault":true,"description":"Antrean pesanan baru masuk dan belum dihubungi sama sekali."},{"id":"sedang_menunggu","label":"Sedang Menunggu Respon","shortLabel":"Menunggu Respon","color":"blue","countsAsCompleted":false,"isDefault":false,"description":"Pesan sudah dikirim ke AC / Toko, sedang menunggu konfirmasi penanganan."},{"id":"sudah_dihubungi","label":"Sudah Dikerjakan / Dihubungi","shortLabel":"Sudah Dihubungi","color":"emerald","countsAsCompleted":true,"isDefault":false,"description":"AC sudah dihubungi melalui WhatsApp dan kendala pesanan sedang ditindaklanjuti."},{"id":"kendala_selesai","label":"Kendala Selesai / Terkirim","shortLabel":"Selesai Terkirim","color":"teal","countsAsCompleted":true,"isDefault":false,"description":"Pesanan Alfagift sudah berhasil dikirimkan atau kendala SLA terselesaikan."},{"id":"tidak_merespon","label":"Tidak Merespon / Butuh Follow-Up","shortLabel":"Perlu Follow-Up","color":"rose","countsAsCompleted":false,"isDefault":false,"description":"AC atau personil toko belum merespon setelah dihubungi dan butuh telepon/tindak lanjut."}],"darkMode":false}$defaults$::jsonb) d;
insert into public.sapa_pic_settings(pic_name,setting_key,value) select p.name,d.key,d.value from public.sapa_pic_profiles p cross join jsonb_each($pod_defaults${"podTemplate":"Halo Selamat {waktu_salam} Pak/Bu {nama_ac},\n\nIzin menginfokan dan mengingatkan untuk operasional toko binaan Bapak/Ibu saat ini terdapat *{jumlah_shipment} pesanan* Alfagift yang masih perlu diselesaikan proses *POD (Proof of Delivery)*.\n\nMohon bantuannya untuk dikoordinasikan ke tim toko agar segera diselesaikan konfirmasi POD-nya hari ini ya Pak/Bu, agar pesanan tidak menggantung.\n\nTerima kasih banyak atas perhatian dan kerja samanya! 🙏","podDelay":8,"podUseSameTab":true,"podSoundEnabled":true}$pod_defaults$::jsonb) d on conflict (pic_name,setting_key) do nothing;
notify pgrst, 'reload schema';
commit;
